-- Mission-first chemical planning: exact Mission evidence, organisation presets and platform intelligence.
create function public.ftf_normalise_chemical_name(p_value text) returns text language sql immutable strict as $$
 select trim(regexp_replace(lower(p_value),'[^a-z0-9]+',' ','g'));
$$;

create table public.platform_chemical_products(
 id uuid primary key default gen_random_uuid(),canonical_name text not null,normalised_name text not null,manufacturer text,apvma_number text,current_version integer not null default 1 check(current_version>0),status text not null default 'VERIFIED' check(status in('VERIFIED','RETIRED')),created_at timestamptz not null default now(),created_by_internal_user_id uuid,unique(normalised_name,manufacturer),unique(apvma_number)
);
create table public.platform_chemical_product_versions(
 id uuid primary key default gen_random_uuid(),product_id uuid not null references public.platform_chemical_products(id),version_number integer not null check(version_number>0),display_name text not null,manufacturer text,apvma_number text,active_ingredient text,formulation text,label_url text,sds_url text,aerial_use_guidance text,jurisdictions jsonb not null default '["AU"]'::jsonb,provenance jsonb not null default '{}'::jsonb,published_at timestamptz not null default now(),published_by_internal_user_id uuid,unique(product_id,version_number),unique(id,product_id)
);
create table public.organisation_chemical_register(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null,operating_location_id uuid,platform_product_id uuid,platform_product_version_id uuid,display_name text not null,preferred_rate numeric,preferred_rate_unit text check(preferred_rate_unit in('L_HA','ML_HA','KG_HA','G_HA')),notes text,row_version integer not null default 1,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organisation_id,id),foreign key(organisation_id) references public.organisations(id),foreign key(organisation_id,operating_location_id) references public.operating_locations(organisation_id,id),foreign key(platform_product_version_id,platform_product_id) references public.platform_chemical_product_versions(id,product_id)
);
create table public.mission_chemical_plan_revisions(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null,operating_location_id uuid not null,mission_id uuid not null,version_number integer not null check(version_number>0),treatment_area_ha numeric not null check(treatment_area_ha>0),application_volume_l_ha numeric not null check(application_volume_l_ha>0),tank_capacity_l numeric not null check(tank_capacity_l>0),total_spray_volume_l numeric not null check(total_spray_volume_l>0),water_required_l numeric not null check(water_required_l>=0),hectares_per_batch numeric not null check(hectares_per_batch>0),batch_count integer not null check(batch_count>0),notes text,created_at timestamptz not null default now(),created_by_internal_user_id uuid not null,unique(organisation_id,id),unique(organisation_id,mission_id,version_number),foreign key(organisation_id,mission_id) references public.missions(organisation_id,id),foreign key(organisation_id,operating_location_id) references public.operating_locations(organisation_id,id),foreign key(organisation_id,created_by_internal_user_id) references public.internal_users(organisation_id,id)
);
create table public.mission_chemical_plan_lines(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null,revision_id uuid not null,mission_id uuid not null,line_number integer not null check(line_number>0),match_state text not null check(match_state in('VERIFIED','UNMATCHED')),platform_product_id uuid,platform_product_version_id uuid,register_entry_id uuid,product_name text not null,normalised_product_name text not null,manufacturer text,apvma_number text,active_ingredient text,formulation text,rate numeric not null check(rate>0),rate_unit text not null check(rate_unit in('L_HA','ML_HA','KG_HA','G_HA')),total_product_quantity numeric not null check(total_product_quantity>0),total_product_unit text not null check(total_product_unit in('L','ML','KG','G')),product_per_batch numeric not null check(product_per_batch>0),snapshot jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(organisation_id,id),unique(organisation_id,revision_id,line_number),foreign key(organisation_id,revision_id) references public.mission_chemical_plan_revisions(organisation_id,id),foreign key(organisation_id,mission_id) references public.missions(organisation_id,id),foreign key(platform_product_version_id,platform_product_id) references public.platform_chemical_product_versions(id,product_id),foreign key(organisation_id,register_entry_id) references public.organisation_chemical_register(organisation_id,id)
);
create table public.chemical_intelligence_reviews(
 id uuid primary key default gen_random_uuid(),source_organisation_id uuid not null,source_mission_id uuid not null,source_revision_id uuid not null,source_line_id uuid not null,normalised_product_name text not null,product_name text not null,manufacturer text,apvma_number text,active_ingredient text,formulation text,status text not null default 'NEW' check(status in('NEW','INVESTIGATING','RETURNED_FOR_RESEARCH','READY_FOR_APPROVAL','APPROVED','DUPLICATE','REJECTED')),research_notes text,recommendation text,evidence jsonb not null default '[]'::jsonb,suggested_duplicate_product_id uuid,published_product_id uuid,row_version integer not null default 1 check(row_version>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by_internal_user_id uuid not null,foreign key(source_organisation_id,source_mission_id) references public.missions(organisation_id,id),foreign key(source_organisation_id,source_revision_id) references public.mission_chemical_plan_revisions(organisation_id,id),foreign key(source_organisation_id,source_line_id) references public.mission_chemical_plan_lines(organisation_id,id),foreign key(source_organisation_id,created_by_internal_user_id) references public.internal_users(organisation_id,id),foreign key(suggested_duplicate_product_id) references public.platform_chemical_products(id),foreign key(published_product_id) references public.platform_chemical_products(id)
);
create table public.chemical_intelligence_review_history(
 id uuid primary key default gen_random_uuid(),review_id uuid not null references public.chemical_intelligence_reviews(id),from_status text,to_status text not null,action text not null,notes text,evidence jsonb not null default '[]'::jsonb,actor_internal_user_id uuid not null,created_at timestamptz not null default now()
);

create index mission_chemical_plan_history_idx on public.mission_chemical_plan_revisions(organisation_id,mission_id,version_number desc);
create index chemical_review_queue_idx on public.chemical_intelligence_reviews(status,updated_at);
create unique index chemical_review_dedupe_idx on public.chemical_intelligence_reviews(source_organisation_id,normalised_product_name,coalesce(manufacturer,''),coalesce(apvma_number,''));

alter table public.platform_chemical_products enable row level security;alter table public.platform_chemical_products force row level security;
alter table public.platform_chemical_product_versions enable row level security;alter table public.platform_chemical_product_versions force row level security;
alter table public.organisation_chemical_register enable row level security;alter table public.organisation_chemical_register force row level security;
alter table public.mission_chemical_plan_revisions enable row level security;alter table public.mission_chemical_plan_revisions force row level security;
alter table public.mission_chemical_plan_lines enable row level security;alter table public.mission_chemical_plan_lines force row level security;
alter table public.chemical_intelligence_reviews enable row level security;alter table public.chemical_intelligence_reviews force row level security;
alter table public.chemical_intelligence_review_history enable row level security;alter table public.chemical_intelligence_review_history force row level security;
create policy organisation_chemical_register_tenant_read on public.organisation_chemical_register for select to authenticated using(public.current_user_has_organisation_access(organisation_id));
create policy mission_chemical_plan_revisions_tenant_read on public.mission_chemical_plan_revisions for select to authenticated using(public.current_user_has_organisation_access(organisation_id));
create policy mission_chemical_plan_lines_tenant_read on public.mission_chemical_plan_lines for select to authenticated using(public.current_user_has_organisation_access(organisation_id));
revoke all on table public.platform_chemical_products from public,anon,authenticated;
revoke all on table public.platform_chemical_product_versions from public,anon,authenticated;
revoke all on table public.organisation_chemical_register from public,anon,authenticated;
revoke all on table public.mission_chemical_plan_revisions from public,anon,authenticated;
revoke all on table public.mission_chemical_plan_lines from public,anon,authenticated;
revoke all on table public.chemical_intelligence_reviews from public,anon,authenticated;
revoke all on table public.chemical_intelligence_review_history from public,anon,authenticated;
grant select,insert,update,delete on table public.platform_chemical_products,public.platform_chemical_product_versions,public.organisation_chemical_register,public.mission_chemical_plan_revisions,public.mission_chemical_plan_lines,public.chemical_intelligence_reviews,public.chemical_intelligence_review_history to service_role;

create function public.ftf_provision_chemical_permissions() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin
 insert into public.permissions(organisation_id,code,description)select new.organisation_id,v.code,v.description from(values
 ('mission.chemicals.read','View Mission chemical evidence'),('mission.chemicals.plan','Plan Mission chemicals'),('chemical.register.read','View organisation chemical register'),('chemical.register.manage','Manage organisation chemical register'),('chemical.review.research','Research platform Chemical Intelligence'),('chemical.review.approve','Approve platform Chemical Intelligence'))v(code,description)on conflict(organisation_id,code)do nothing;
 if new.code='admin'then insert into public.role_permissions(organisation_id,role_id,permission_id)select new.organisation_id,new.id,p.id from public.permissions p where p.organisation_id=new.organisation_id and p.code in('mission.chemicals.read','mission.chemicals.plan','chemical.register.read','chemical.register.manage')on conflict do nothing;end if;return new;
end$$;
create trigger roles_provision_chemical_permissions after insert on public.roles for each row execute function public.ftf_provision_chemical_permissions();
insert into public.permissions(organisation_id,code,description)select o.id,v.code,v.description from public.organisations o cross join(values ('mission.chemicals.read','View Mission chemical evidence'),('mission.chemicals.plan','Plan Mission chemicals'),('chemical.register.read','View organisation chemical register'),('chemical.register.manage','Manage organisation chemical register'),('chemical.review.research','Research platform Chemical Intelligence'),('chemical.review.approve','Approve platform Chemical Intelligence'))v(code,description)on conflict(organisation_id,code)do nothing;
insert into public.role_permissions(organisation_id,role_id,permission_id)select r.organisation_id,r.id,p.id from public.roles r join public.permissions p on p.organisation_id=r.organisation_id and p.code in('mission.chemicals.read','mission.chemicals.plan','chemical.register.read','chemical.register.manage')where r.code='admin'on conflict do nothing;

create function public.ftf_read_mission_chemical_plan(p_organisation_id uuid,p_mission_id uuid,p_history boolean default false) returns setof jsonb language sql security definer set search_path=public,pg_temp as $$
 select to_jsonb(r)||jsonb_build_object('lines',coalesce((select jsonb_agg(to_jsonb(l)order by l.line_number)from public.mission_chemical_plan_lines l where l.organisation_id=r.organisation_id and l.revision_id=r.id),'[]'::jsonb))from public.mission_chemical_plan_revisions r where r.organisation_id=p_organisation_id and r.mission_id=p_mission_id and (p_history or r.version_number=(select max(x.version_number)from public.mission_chemical_plan_revisions x where x.organisation_id=p_organisation_id and x.mission_id=p_mission_id))order by r.version_number desc;
$$;

create function public.ftf_search_chemical_intelligence(p_query text,p_limit integer default 20)returns setof jsonb language sql security definer set search_path=public,pg_temp as $$
 select to_jsonb(p)||jsonb_build_object('version',to_jsonb(v))from public.platform_chemical_products p join public.platform_chemical_product_versions v on v.product_id=p.id and v.version_number=p.current_version where p.status='VERIFIED'and(p.normalised_name like '%'||public.ftf_normalise_chemical_name(p_query)||'%'or coalesce(p.apvma_number,'')=trim(p_query))order by p.canonical_name limit least(greatest(p_limit,1),50);
$$;

create function public.ftf_save_mission_chemical_plan(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_expected_version integer,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_mission public.missions%rowtype;v_current integer;v_revision public.mission_chemical_plan_revisions%rowtype;v_line jsonb;v_saved public.mission_chemical_plan_lines%rowtype;v_area numeric;v_volume numeric;v_tank numeric;v_total numeric;v_water numeric:=0;v_rate numeric;v_qty numeric;v_per_batch numeric;v_batches integer;v_index integer:=0;v_unit text;v_match text;v_norm text;v_review uuid;begin
 select * into v_mission from public.missions where organisation_id=p_organisation_id and id=p_mission_id and archived_at is null for update;if not found then return jsonb_build_object('not_found',true);end if;
 if not exists(select 1 from public.memberships m join public.membership_operating_location_assignments a on a.organisation_id=m.organisation_id and a.membership_id=m.id where m.organisation_id=p_organisation_id and m.internal_user_id=p_actor_internal_user_id and m.is_active and m.archived_at is null and a.operating_location_id=v_mission.operating_location_id and a.is_active and a.archived_at is null)then return jsonb_build_object('location_forbidden',true);end if;
 select coalesce(max(version_number),0)into v_current from public.mission_chemical_plan_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id;if v_current<>p_expected_version then return jsonb_build_object('conflict',true,'current_version',v_current);end if;
 v_area=(p_payload->>'treatmentAreaHa')::numeric;v_volume=(p_payload->>'applicationVolumeLHa')::numeric;v_tank=(p_payload->>'tankCapacityL')::numeric;if v_area<=0 or v_volume<=0 or v_tank<=0 or jsonb_array_length(coalesce(p_payload->'lines','[]'))=0 then raise exception 'chemical plan requires positive area, application volume, tank capacity and lines';end if;
 v_total=round(v_area*v_volume,3);v_batches=ceil(v_total/v_tank);insert into public.mission_chemical_plan_revisions(organisation_id,operating_location_id,mission_id,version_number,treatment_area_ha,application_volume_l_ha,tank_capacity_l,total_spray_volume_l,water_required_l,hectares_per_batch,batch_count,notes,created_by_internal_user_id)values(p_organisation_id,v_mission.operating_location_id,p_mission_id,v_current+1,v_area,v_volume,v_tank,v_total,0,round(v_tank/v_volume,3),v_batches,nullif(p_payload->>'notes',''),p_actor_internal_user_id)returning * into v_revision;
 for v_line in select value from jsonb_array_elements(p_payload->'lines')loop v_index=v_index+1;v_rate=(v_line->>'rate')::numeric;v_unit=upper(v_line->>'rateUnit');v_match=upper(coalesce(v_line->>'matchState','UNMATCHED'));v_norm=public.ftf_normalise_chemical_name(v_line->>'productName');if v_rate<=0 or v_unit not in('L_HA','ML_HA','KG_HA','G_HA')or v_match not in('VERIFIED','UNMATCHED')or v_norm=''then raise exception 'chemical line is invalid';end if;v_qty=round(v_rate*v_area,3);v_per_batch=round(v_rate*(v_tank/v_volume),3);
  insert into public.mission_chemical_plan_lines(organisation_id,revision_id,mission_id,line_number,match_state,platform_product_id,platform_product_version_id,register_entry_id,product_name,normalised_product_name,manufacturer,apvma_number,active_ingredient,formulation,rate,rate_unit,total_product_quantity,total_product_unit,product_per_batch,snapshot)values(p_organisation_id,v_revision.id,p_mission_id,v_index,v_match,nullif(v_line->>'platformProductId','')::uuid,nullif(v_line->>'platformProductVersionId','')::uuid,nullif(v_line->>'registerEntryId','')::uuid,trim(v_line->>'productName'),v_norm,nullif(trim(v_line->>'manufacturer'),''),nullif(trim(v_line->>'apvmaNumber'),''),nullif(trim(v_line->>'activeIngredient'),''),nullif(trim(v_line->>'formulation'),''),v_rate,v_unit,v_qty,case when v_unit='L_HA'then'L'when v_unit='ML_HA'then'ML'when v_unit='KG_HA'then'KG'else'G'end,v_per_batch,v_line)returning * into v_saved;
  if v_unit in('L_HA','ML_HA')then v_water=v_water+case when v_unit='L_HA'then v_qty else v_qty/1000 end;end if;
  if v_match='UNMATCHED'then insert into public.chemical_intelligence_reviews(source_organisation_id,source_mission_id,source_revision_id,source_line_id,normalised_product_name,product_name,manufacturer,apvma_number,active_ingredient,formulation,created_by_internal_user_id)values(p_organisation_id,p_mission_id,v_revision.id,v_saved.id,v_norm,v_saved.product_name,v_saved.manufacturer,v_saved.apvma_number,v_saved.active_ingredient,v_saved.formulation,p_actor_internal_user_id)on conflict(source_organisation_id,normalised_product_name,(coalesce(manufacturer,'')),(coalesce(apvma_number,'')))do update set updated_at=now()returning id into v_review;end if;
 end loop;
 update public.mission_chemical_plan_revisions set water_required_l=greatest(total_spray_volume_l-v_water,0)where id=v_revision.id returning * into v_revision;
 insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'mission.chemicals_planned','mission',p_mission_id,jsonb_build_object('revision_id',v_revision.id,'version',v_revision.version_number));
 insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'operational.mission.chemicals_planned','mission',p_mission_id,jsonb_build_object('revision_id',v_revision.id,'version',v_revision.version_number));
 return jsonb_build_object('record',(select x from public.ftf_read_mission_chemical_plan(p_organisation_id,p_mission_id,false)x),'unmatched_review_created',v_review is not null);
end$$;

create function public.ftf_list_chemical_reviews(p_status text default null,p_limit integer default 100)returns setof jsonb language sql security definer set search_path=public,pg_temp as $$select to_jsonb(r)from public.chemical_intelligence_reviews r where p_status is null or r.status=p_status order by r.updated_at asc limit least(greatest(p_limit,1),200);$$;
create function public.ftf_transition_chemical_review(p_actor_internal_user_id uuid,p_review_id uuid,p_expected_version integer,p_action text,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v public.chemical_intelligence_reviews%rowtype;v_from text;v_to text;v_product public.platform_chemical_products%rowtype;begin select * into v from public.chemical_intelligence_reviews where id=p_review_id for update;if not found then return jsonb_build_object('not_found',true);end if;if v.row_version<>p_expected_version then return jsonb_build_object('conflict',true,'current_version',v.row_version);end if;v_from=v.status;v_to=case upper(p_action)when'START_RESEARCH'then'INVESTIGATING'when'READY_FOR_APPROVAL'then'READY_FOR_APPROVAL'when'RETURN'then'RETURNED_FOR_RESEARCH'when'APPROVE'then'APPROVED'when'DUPLICATE'then'DUPLICATE'when'REJECT'then'REJECTED'else null end;if v_to is null then raise exception 'invalid review action';end if;if upper(p_action)in('APPROVE','DUPLICATE','REJECT','RETURN')and v.status<>'READY_FOR_APPROVAL'then raise exception 'review is not ready for approval';end if;if upper(p_action)='APPROVE'then insert into public.platform_chemical_products(canonical_name,normalised_name,manufacturer,apvma_number,created_by_internal_user_id)values(v.product_name,v.normalised_product_name,v.manufacturer,v.apvma_number,p_actor_internal_user_id)returning * into v_product;insert into public.platform_chemical_product_versions(product_id,version_number,display_name,manufacturer,apvma_number,active_ingredient,formulation,provenance,published_by_internal_user_id)values(v_product.id,1,v.product_name,v.manufacturer,v.apvma_number,v.active_ingredient,v.formulation,jsonb_build_object('review_id',v.id),p_actor_internal_user_id);end if;update public.chemical_intelligence_reviews set status=v_to,research_notes=coalesce(p_payload->>'researchNotes',research_notes),recommendation=coalesce(p_payload->>'recommendation',recommendation),evidence=coalesce(p_payload->'evidence',evidence),suggested_duplicate_product_id=coalesce(nullif(p_payload->>'duplicateProductId','')::uuid,suggested_duplicate_product_id),published_product_id=case when v_product.id is not null then v_product.id else published_product_id end,row_version=row_version+1,updated_at=now()where id=v.id returning * into v;insert into public.chemical_intelligence_review_history(review_id,from_status,to_status,action,notes,evidence,actor_internal_user_id)values(v.id,v_from,v_to,upper(p_action),p_payload->>'notes',coalesce(p_payload->'evidence','[]'::jsonb),p_actor_internal_user_id);insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(v.source_organisation_id,p_actor_internal_user_id,'chemical.review_transitioned','chemical_intelligence_review',v.id,jsonb_build_object('from',v_from,'to',v_to,'action',upper(p_action)));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(v.source_organisation_id,'platform.chemical.review_transitioned','chemical_intelligence_review',v.id,jsonb_build_object('from',v_from,'to',v_to,'action',upper(p_action)));return jsonb_build_object('record',to_jsonb(v));end$$;

insert into public.platform_chemical_products(id,canonical_name,normalised_name,manufacturer,apvma_number,status)values('a1000000-0000-4000-8000-000000000001','Grazon Extra','grazon extra','Corteva Agriscience',null,'VERIFIED')on conflict do nothing;
insert into public.platform_chemical_product_versions(product_id,version_number,display_name,manufacturer,active_ingredient,formulation,aerial_use_guidance,provenance)values('a1000000-0000-4000-8000-000000000001',1,'Grazon Extra','Corteva Agriscience','Triclopyr + Picloram + Aminopyralid','Liquid','Use only according to the current approved label.',jsonb_build_object('source','existing Spray Command catalogue','verification_scope','Production Beta seed'))on conflict do nothing;

revoke all on function public.ftf_normalise_chemical_name(text),public.ftf_read_mission_chemical_plan(uuid,uuid,boolean),public.ftf_search_chemical_intelligence(text,integer),public.ftf_save_mission_chemical_plan(uuid,uuid,uuid,integer,jsonb),public.ftf_list_chemical_reviews(text,integer),public.ftf_transition_chemical_review(uuid,uuid,integer,text,jsonb),public.ftf_provision_chemical_permissions()from public,anon,authenticated;
grant execute on function public.ftf_normalise_chemical_name(text),public.ftf_read_mission_chemical_plan(uuid,uuid,boolean),public.ftf_search_chemical_intelligence(text,integer),public.ftf_save_mission_chemical_plan(uuid,uuid,uuid,integer,jsonb),public.ftf_list_chemical_reviews(text,integer),public.ftf_transition_chemical_review(uuid,uuid,integer,text,jsonb)to service_role;
